{"path":"/root/output/export_object_obj.mjs","content":"import * as THREE from 'three';
import fs from 'fs';
import path from 'path';
import { pathToFileURL } from 'url';

const inputPath = '/root/data/object.js';
const outputPath = '/root/output/object.obj';

const axisMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2); // Blender Z-up

function bakeGeometry(geometry, matrix) {
  let geom = geometry.clone();
  if (geom.index) geom = geom.toNonIndexed();
  geom.applyMatrix4(matrix);
  if (!geom.attributes.normal) geom.computeVertexNormals();
  return geom;
}

function appendGeometryOBJ(geom, state, objectName = 'object') {
  const pos = geom.attributes.position;
  const nor = geom.attributes.normal;
  const vertCount = pos.count;
  state.lines.push(`o ${objectName}`);
  for (let i = 0; i < vertCount; i++) {
    state.lines.push(`v ${pos.getX(i)} ${pos.getY(i)} ${pos.getZ(i)}`);
  }
  if (nor) {
    for (let i = 0; i < nor.count; i++) {
      state.lines.push(`vn ${nor.getX(i)} ${nor.getY(i)} ${nor.getZ(i)}`);
    }
  }
  for (let i = 0; i < vertCount; i += 3) {
    const a = state.vertexOffset + i + 1;
    const b = state.vertexOffset + i + 2;
    const c = state.vertexOffset + i + 3;
    if (nor) {
      const na = state.normalOffset + i + 1;
      const nb = state.normalOffset + i + 2;
      const nc = state.normalOffset + i + 3;
      state.lines.push(`f ${a}//${na} ${b}//${nb} ${c}//${nc}`);
    } else {
      state.lines.push(`f ${a} ${b} ${c}`);
    }
  }
  state.vertexOffset += vertCount;
  if (nor) state.normalOffset += nor.count;
}

async function main() {
  const mod = await import(pathToFileURL(inputPath).href);
  if (typeof mod.createScene !== 'function') {
    throw new Error('object.js does not export createScene()');
  }
  const root = mod.createScene();
  root.updateMatrixWorld(true);

  const state = { lines: ['# Exported from Three.js scene', ''], vertexOffset: 0, normalOffset: 0 };

  root.traverse((obj) => {
    if (!obj.isMesh && !obj.isInstancedMesh) return;

    if (obj.isInstancedMesh) {
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < obj.count; i++) {
        obj.getMatrixAt(i, instanceMatrix);
        const worldMatrix = new THREE.Matrix4().multiplyMatrices(obj.matrixWorld, instanceMatrix);
        const finalMatrix = new THREE.Matrix4().multiplyMatrices(axisMatrix, worldMatrix);
        const geom = bakeGeometry(obj.geometry, finalMatrix);
        appendGeometryOBJ(geom, state, `${obj.name || 'instanced_mesh'}_${i}`);
      }
    } else {
      const finalMatrix = new THREE.Matrix4().multiplyMatrices(axisMatrix, obj.matrixWorld);
      const geom = bakeGeometry(obj.geometry, finalMatrix);
      appendGeometryOBJ(geom, state, obj.name || 'mesh');
    }
  });

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, state.lines.join('\n') + '\n', 'utf8');
  console.log(`Wrote ${outputPath}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
"}
